<?php
 namespace Pterodactyl\Services\Dezerx\Importer; use Throwable; use phpseclib3\Net\SFTP; use phpseclib3\Net\SFTP\Stream; use phpseclib3\Crypt\PublicKeyLoader; use Illuminate\Support\Facades\Log; class SftpClient implements RemoteFilesystem { use RemoteWalk; private const TIMEOUT = 20; private const REMOTE_DIRECTORY = 2; private ?SFTP $sftp = null; public function __construct(private readonly Credentials $credentials) { } public function open(): array { $refusal = $this->credentials->refusal(); if ($refusal !== null) { return ['ok' => false, 'error' => $refusal, 'banner' => null]; } try { $sftp = new SFTP((string) $this->credentials->connectAddress(), $this->credentials->port, self::TIMEOUT); } catch (Throwable $exception) { return ['ok' => false, 'error' => 'That host could not be reached: ' . $exception->getMessage(), 'banner' => null]; } try { $authenticated = $this->credentials->auth === 'key' ? $this->loginWithKey($sftp) : $sftp->login($this->credentials->username, $this->credentials->secret); } catch (Throwable $exception) { Log::info('An import login failed', [ 'host' => $this->credentials->host, 'error' => $exception->getMessage(), ]); return ['ok' => false, 'error' => 'That login was refused: ' . $exception->getMessage(), 'banner' => null]; } if (!$authenticated) { return [ 'ok' => false, 'error' => $this->credentials->auth === 'key' ? 'That key was refused by the host.' : 'That username and password were refused by the host.', 'banner' => null, ]; } $this->sftp = $sftp; return ['ok' => true, 'error' => null, 'banner' => trim((string) $sftp->getServerIdentification()) ?: null]; } private function loginWithKey(SFTP $sftp): bool { $key = PublicKeyLoader::load( $this->credentials->secret, $this->credentials->passphrase ?: false, ); return $sftp->login($this->credentials->username, $key); } public function listing(string $path): ?array { if ($this->sftp === null) { return null; } $raw = $this->sftp->rawlist($this->clean($path)); if (!is_array($raw)) { return null; } $entries = []; foreach ($raw as $name => $meta) { $name = (string) $name; if ($name === '.' || $name === '..' || !is_array($meta)) { continue; } $entries[] = [ 'name' => $name, 'size' => (int) ($meta['size'] ?? 0), 'directory' => ($meta['type'] ?? null) === self::REMOTE_DIRECTORY, ]; } usort($entries, fn (array $a, array $b) => [$b['directory'], $a['name']] <=> [$a['directory'], $b['name']]); return $entries; } public function openReadStream(string $path): mixed { if ($this->sftp === null) { return false; } $clean = $this->clean($path); if (str_contains($clean, '#') || str_contains($clean, '?')) { return $this->bufferedReadStream($clean); } Stream::register(); $context = stream_context_create(['sftp' => ['sftp' => $this->sftp]]); try { return @fopen('sftp://import/' . ltrim($clean, '/'), 'r', false, $context); } catch (Throwable $exception) { Log::warning('An import could not read a remote file', [ 'host' => $this->credentials->host, 'path' => $path, 'error' => $exception->getMessage(), ]); return false; } } private function bufferedReadStream(string $path): mixed { $stream = fopen('php://temp/maxmemory:8388608', 'w+b'); if ($stream === false) { return false; } try { if ($this->sftp?->get($path, $stream) === false) { fclose($stream); return false; } } catch (Throwable $exception) { fclose($stream); Log::warning('An import could not read a remote file', [ 'host' => $this->credentials->host, 'path' => $path, 'error' => $exception->getMessage(), ]); return false; } rewind($stream); return $stream; } public function isDirectory(string $path): bool { return $this->sftp !== null && $this->sftp->is_dir($this->clean($path)); } public function close(): void { try { $this->sftp?->disconnect(); } catch (Throwable) { } $this->sftp = null; } private function clean(string $path): string { $path = trim(str_replace('\\', '/', $path)); return $path === '' ? '.' : $path; } } 